import { exportJWK, generateKeyPair, SignJWT } from "jose";

export async function makeTestJwtIssuer() {
  const { publicKey, privateKey } = await generateKeyPair("EdDSA", { crv: "Ed25519" });
  const jwk = await exportJWK(publicKey);
  const mint = (claims: Record<string, unknown>, exp = "5m") =>
    new SignJWT(claims).setProtectedHeader({ alg: "EdDSA" }).setIssuedAt().setExpirationTime(exp).sign(privateKey);
  return { publicKey, jwk, mint };
}
